                m.depth = r0.uintMax(4294967295L)
                return m
            }
        }
    }

    /** Dismissed reports that the user closed a modal (swipe down, back button). */
    data class Dismissed(
        var tag: Long = 0L,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
        }

        companion object {
            fun read(r0: WireReader): Dismissed {
                val m = Dismissed()
                m.tag = r0.uintMax(4294967295L)
                return m
            }
        }
    }

    /** Selected reports that the user picked the tab at Index. */
    data class Selected(
        var tag: Long = 0L,
        var index: Long = 0L,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
            w.uint(this.index)
        }

        companion object {
            fun read(r0: WireReader): Selected {
                val m = Selected()
                m.tag = r0.uintMax(4294967295L)
                m.index = r0.uintMax(4294967295L)
                return m
            }
        }
    }

    /** Resized reports the size a stack or tab bar gives its screens. Bottom is how much of that height a bar covers (iOS tabs run under the tab bar); content should keep clear of it. */
    data class Resized(
        var tag: Long = 0L,
        var w: Float = 0f,
        var h: Float = 0f,
        var bottom: Float = 0f,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
            w.f32(this.w)
            w.f32(this.h)
            w.f32(this.bottom)
        }

        companion object {
            fun read(r0: WireReader): Resized {
                val m = Resized()
                m.tag = r0.uintMax(4294967295L)
                m.w = r0.f32()
                m.h = r0.f32()
                m.bottom = r0.f32()
                return m
            }
        }
    }

    /** Submitted reports Return on an input that submits (Input.Submit). */
    data class Submitted(
        var tag: Long = 0L,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
        }

        companion object {
            fun read(r0: WireReader): Submitted {
                val m = Submitted()
                m.tag = r0.uintMax(4294967295L)
                return m
            }
        }
    }

    /** Changed reports an input's new text. */
    data class Changed(
        var tag: Long = 0L,
        var text: String = "",
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
            w.string(this.text)
        }

        companion object {
            fun read(r0: WireReader): Changed {
                val m = Changed()
                m.tag = r0.uintMax(4294967295L)
                m.text = r0.string()
                return m
