    /** MeasureText asks the host for a text's size (synchronous host call). */
    data class MeasureText(
        var text: String = "",
        var font: Font = Font(),
        var maxWidth: Float = 0f,
        var lines: Long = 0L,
    ) : Message {
        fun write(w: WireWriter) {
            w.string(this.text)
            this.font.write(w)
            w.f32(this.maxWidth)
            w.uint(this.lines)
        }

        companion object {
            fun read(r0: WireReader): MeasureText {
                val m = MeasureText()
                m.text = r0.string()
                m.font = Font.read(r0)
                m.maxWidth = r0.f32()
                m.lines = r0.uintMax(4294967295L)
                return m
            }
        }
    }

    /** TextSize answers MeasureText. */
    data class TextSize(
        var w: Float = 0f,
        var h: Float = 0f,
    ) : Message {
        fun write(w: WireWriter) {
            w.f32(this.w)
            w.f32(this.h)
        }

        companion object {
            fun read(r0: WireReader): TextSize {
                val m = TextSize()
                m.w = r0.f32()
                m.h = r0.f32()
                return m
            }
        }
    }

    /** PluginCall asks a native plugin to run a method (synchronous host call). The host answers at once with PluginAck and sends the outcome later as a PluginResult with the same ID. Args and results are JSON. */
    data class PluginCall(
        var id: Long = 0L,
        var plugin: String = "",
        var method: String = "",
        var args: String = "",
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.id)
            w.string(this.plugin)
            w.string(this.method)
            w.string(this.args)
        }

        companion object {
            fun read(r0: WireReader): PluginCall {
                val m = PluginCall()
                m.id = r0.uint()
                m.plugin = r0.string()
                m.method = r0.string()
                m.args = r0.string()
                return m
            }
        }
    }

    /** PluginAck answers PluginCall: Err is empty when the call started. */
    data class PluginAck(
        var err: String = "",
    ) : Message {
        fun write(w: WireWriter) {
            w.string(this.err)
        }

        companion object {
            fun read(r0: WireReader): PluginAck {
                val m = PluginAck()
                m.err = r0.string()
                return m
            }
        }
    }

    /** PluginResult is a plugin call's outcome. A failure has a Code ("unavailable", "cancelled", "denied", "not_found", "failed") and Err. */
    data class PluginResult(
        var id: Long = 0L,
        var value: String = "",
        var code: String = "",
        var err: String = "",
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.id)
            w.string(this.value)
            w.string(this.code)
            w.string(this.err)
        }

        companion object {
            fun read(r0: WireReader): PluginResult {
                val m = PluginResult()
                m.id = r0.uint()
                m.value = r0.string()
                m.code = r0.string()
                m.err = r0.string()
                return m
            }
        }
    }

    /** Toggled reports that the user flipped a switch. */
    data class Toggled(
        var tag: Long = 0L,
