    /** Slid reports the value the user dragged a slider to. */
    data class Slid(
        var tag: Long = 0L,
        var value: Float = 0f,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
            w.f32(this.value)
        }

        companion object {
            fun read(r0: WireReader): Slid {
                val m = Slid()
                m.tag = r0.uintMax(4294967295L)
