    /** LongPressed reports a long press on a pressable that asked for them. */
    data class LongPressed(
        var tag: Long = 0L,
    ) : Message {
        fun write(w: WireWriter) {
            w.uint(this.tag)
        }

        companion object {
            fun read(r0: WireReader): LongPressed {
                val m = LongPressed()
                m.tag = r0.uintMax(4294967295L)
                return m
