    /** Op changes one native view. */
    sealed interface Op

    fun writeOp(w: WireWriter, v: Op?) {
        when (v) {
            null -> w.uint(0)
            is Create -> { w.uint(1); v.write(w) }
            is Destroy -> { w.uint(2); v.write(w) }
            is Children -> { w.uint(3); v.write(w) }
            is Frame -> { w.uint(4); v.write(w) }
            is Box -> { w.uint(5); v.write(w) }
            is Text -> { w.uint(6); v.write(w) }
            is Image -> { w.uint(7); v.write(w) }
            is Input -> { w.uint(8); v.write(w) }
            is Screen -> { w.uint(9); v.write(w) }
            is TabItem -> { w.uint(10); v.write(w) }
            is TabSelect -> { w.uint(11); v.write(w) }
            is Chrome -> { w.uint(12); v.write(w) }
            is Present -> { w.uint(13); v.write(w) }
            is Scroll -> { w.uint(14); v.write(w) }
            is Draw -> { w.uint(15); v.write(w) }
            is Slider -> { w.uint(16); v.write(w) }
            is Switch -> { w.uint(17); v.write(w) }
            is Spinner -> { w.uint(18); v.write(w) }
        }
    }

    fun readOp(r0: WireReader): Op? = when (val i = r0.uint()) {
        0L -> null
        1L -> Create.read(r0)
        2L -> Destroy.read(r0)
        3L -> Children.read(r0)
        4L -> Frame.read(r0)
        5L -> Box.read(r0)
        6L -> Text.read(r0)
        7L -> Image.read(r0)
        8L -> Input.read(r0)
        9L -> Screen.read(r0)
        10L -> TabItem.read(r0)
        11L -> TabSelect.read(r0)
        12L -> Chrome.read(r0)
        13L -> Present.read(r0)
        14L -> Scroll.read(r0)
        15L -> Draw.read(r0)
        16L -> Slider.read(r0)
        17L -> Switch.read(r0)
        18L -> Spinner.read(r0)
        else -> throw WireException("unknown Op variant $i")
    }

    /** Any top-level message in this schema. */
    sealed interface Message

    fun writeMessage(w: WireWriter, v: Message?) {
        when (v) {
            null -> w.uint(0)
            is Commit -> { w.uint(1); v.write(w) }
            is Viewport -> { w.uint(2); v.write(w) }
            is Press -> { w.uint(3); v.write(w) }
            is Scrolled -> { w.uint(4); v.write(w) }
            is Popped -> { w.uint(5); v.write(w) }
            is Dismissed -> { w.uint(6); v.write(w) }
            is Selected -> { w.uint(7); v.write(w) }
            is Resized -> { w.uint(8); v.write(w) }
            is Submitted -> { w.uint(9); v.write(w) }
            is Changed -> { w.uint(10); v.write(w) }
            is MeasureText -> { w.uint(11); v.write(w) }
            is TextSize -> { w.uint(12); v.write(w) }
            is PluginCall -> { w.uint(13); v.write(w) }
            is PluginAck -> { w.uint(14); v.write(w) }
            is PluginResult -> { w.uint(15); v.write(w) }
            is Toggled -> { w.uint(16); v.write(w) }
            is Refresh -> { w.uint(17); v.write(w) }
            is Reattach -> { w.uint(18); v.write(w) }
            is Open -> { w.uint(19); v.write(w) }
            is Slid -> { w.uint(20); v.write(w) }
            is LongPressed -> { w.uint(21); v.write(w) }
        }
    }

    fun readMessage(r0: WireReader): Message? = when (val i = r0.uint()) {
        0L -> null
        1L -> Commit.read(r0)
        2L -> Viewport.read(r0)
        3L -> Press.read(r0)
        4L -> Scrolled.read(r0)
        5L -> Popped.read(r0)
        6L -> Dismissed.read(r0)
        7L -> Selected.read(r0)
        8L -> Resized.read(r0)
        9L -> Submitted.read(r0)
        10L -> Changed.read(r0)
        11L -> MeasureText.read(r0)
        12L -> TextSize.read(r0)
        13L -> PluginCall.read(r0)
        14L -> PluginAck.read(r0)
        15L -> PluginResult.read(r0)
        16L -> Toggled.read(r0)
        17L -> Refresh.read(r0)
        18L -> Reattach.read(r0)
        19L -> Open.read(r0)
        20L -> Slid.read(r0)
        21L -> LongPressed.read(r0)
        else -> throw WireException("unknown Message variant $i")
    }

    /** The message's wire encoding: its id, then its fields. */
    fun encode(m: Message): ByteArray {
        val w = WireWriter()
        writeMessage(w, m)
        return w.toByteArray()
    }

    /** Reads exactly one message; throws WireException on bad input. */
    fun decode(bytes: ByteArray): Message {
        val r = WireReader(bytes)
        val m = readMessage(r)
        r.done()
        return m ?: throw WireException("no message")
    }
}
